 readonly ComboBox filter=new(){Width=130,Height=32,ItemsSource=new[]{"全部","数值","枚举","开关","单选","ROI设置","文件路径","训练模型设置"},SelectedIndex=0,Tag="GroupRunFilter"};readonly TextBlock error=new(){Foreground=Brushes.DarkRed};bool rebuilding;
 public GroupRunConfigurationWindow(Func<ProcedureDocument> body,ModuleRegistry registry,Action<WorkflowConfiguration> save,Action<StackPanel,WorkflowRunParameter,ProcedureDocument> commands,Action<StackPanel,ProcedureDocument> categories,Dictionary<string,bool> expandedCategories){
  this.body=body;this.registry=registry;this.save=save;this.commands=commands;this.categories=categories;this.expandedCategories=expandedCategories;selectedCategory=body().Configuration.RunCategories?.FirstOrDefault()?.Id;knownCategories=(body().Configuration.RunCategories??[]).Select(g=>g.Id).ToHashSet();Title="设置运行参数";Width=1100;Height=680;ShowInTaskbar=false;WindowStartupLocation=WindowStartupLocation.CenterOwner;FontFamily=new FontFamily("Microsoft YaHei");FontSize=14;Background=(Brush)new BrushConverter().ConvertFromString("#f2f3f5")!;Foreground=(Brush)new BrushConverter().ConvertFromString("#4c4c4c")!;
  var root=new DockPanel{Background=Background};var footer=new DockPanel{Height=44,Margin=new Thickness(12,0,12,0)};var confirm=new Button{Content="确定",Width=80,Height=28,Tag="GroupRunConfigurationConfirm"};confirm.Click+=(_,_)=>Close();DockPanel.SetDock(confirm,Dock.Right);footer.Children.Add(confirm);footer.Children.Add(error);DockPanel.SetDock(footer,Dock.Bottom);root.Children.Add(footer);
  var columns=new Grid{Margin=new Thickness(0,10,0,0)};columns.ColumnDefinitions.Add(new(){Width=new GridLength(370)});columns.ColumnDefinitions.Add(new());var left=new DockPanel{Background=Brushes.White};var heading=new TextBlock{Text="选择列表",Height=37,Padding=new Thickness(12,8,0,0),FontWeight=FontWeights.Bold};DockPanel.SetDock(heading,Dock.Top);left.Children.Add(heading);var find=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal,Height=37,Margin=new Thickness(12,0,0,0)};find.Children.Add(filter);find.Children.Add(search);DockPanel.SetDock(find,Dock.Top);left.Children.Add(find);left.Children.Add(tree);columns.Children.Add(left);
