 void Change(Func<WorkflowConfiguration,WorkflowConfiguration> update,bool expandSelectedOnAdd=false){try{var before=body().Configuration;var after=update(before);save(after);if(expandSelectedOnAdd&&after.RunParameters.Count>before.RunParameters.Count&&selectedCategory is not null)expandedCategories[selectedCategory]=true;error.Text="";}catch(Exception e){error.Text=e.Message;}Rebuild();}
 void BuildTree(){if(rebuilding)return;rebuilding=true;try{tree.Items.Clear();var current=body();foreach(var node in current.Nodes){var descriptor=registry.GetDescriptor(node);
  var options=descriptor.Parameters.Select(p=>(p.Name,Input:false,Kind:p.Kind.ToString(),Type:EditorType(p))).Concat(descriptor.Inputs.Select(p=>(p.Name,Input:true,Kind:p.Kind.ToString(),Type:p.Kind is DataKind.Integer or DataKind.Number?1:-1))).Where(o=>(filter.SelectedIndex==0||o.Type==filter.SelectedIndex)&&(node.Name+"."+o.Name).Contains(search.Text,StringComparison.OrdinalIgnoreCase)).ToArray();if(options.Length==0)continue;
