  var all=new CheckBox{Content=node.Name,IsThreeState=true,Tag="GroupRunModule:"+node.Id};int count=options.Count(o=>Contains(o.Name,o.Input));all.IsChecked=count==0?false:count==options.Length?true:null;var group=new TreeViewItem{Header=all,IsExpanded=true};
