  foreach(var option in options){var check=new CheckBox{Content=option.Name,Tag="GroupRunCandidate:"+node.Id+":"+option.Name+":"+option.Input,ToolTip=option.Kind,IsChecked=Contains(option.Name,option.Input)};check.Click+=(_,_)=>Change(c=>{if(check.IsChecked==true)c=PrepareCategory(c);return c with{RunParameters=check.IsChecked==true?c.RunParameters.Append(NewProxy(c,node.Id,option.Name,node.Name+"_"+option.Name,option.Input)).ToArray():c.RunParameters.Where(p=>p.NodeId!=node.Id||p.Parameter!=option.Name||p.IsInput!=option.Input).ToArray()};},expandSelectedOnAdd:check.IsChecked==true);group.Items.Add(check);}tree.Items.Add(group);}
 }finally{rebuilding=false;}}
 WorkflowConfiguration PrepareCategory(WorkflowConfiguration configuration){if((configuration.RunCategories?.Count??0)==0){selectedCategory=Guid.NewGuid().ToString("N");return configuration with{RunCategories=[new(selectedCategory,"分组0")]};}if(selectedCategory is null||!configuration.RunCategories!.Any(g=>g.Id==selectedCategory))throw new InvalidOperationException("请先选择分组");return configuration;}
 WorkflowRunParameter NewProxy(WorkflowConfiguration configuration,string node,string parameter,string label,bool input){label=parameter;WorkflowConfiguration.CheckName(label);var original=label;int number=1;while(configuration.RunParameters.Any(p=>p.Label==label))label=original+(number++);WorkflowConfiguration.CheckName(label);return new(Guid.NewGuid().ToString("N"),node,parameter,label,input){CategoryId=selectedCategory};}
 public void SelectCategory(string id){if(!body().Configuration.RunCategories!.Any(g=>g.Id==id))throw new InvalidOperationException("分组不存在");selectedCategory=id;foreach(var pair in categoryViews)pair.Value.BorderBrush=pair.Key==id?System.Windows.Media.Brushes.DarkOrange:System.Windows.Media.Brushes.Transparent;}
 object CategoryHeader(WorkflowRunCategory category,UIElement original){var old=(DockPanel)original;var children=old.Children.Cast<UIElement>().ToArray();old.Children.Clear();var grid=new Grid{Width=660};grid.ColumnDefinitions.Add(new());grid.ColumnDefinitions.Add(new(){Width=new GridLength(90)});var name=children.OfType<TextBox>().Single();name.FontWeight=FontWeights.Bold;grid.Children.Add(name);var actions=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal};foreach(var prefix in new[]{"GroupCategoryUp:","GroupCategoryDown:","GroupCategoryDelete:"})actions.Children.Add(children.OfType<Button>().Single(b=>Equals(b.Tag,prefix+category.Id)));Grid.SetColumn(actions,1);grid.Children.Add(actions);return grid;}
 static int EditorType(ParameterDescriptor p)=>p.Editor?.Kind switch{ParameterEditorKind.Enumeration=>2,ParameterEditorKind.Roi=>5,ParameterEditorKind.File or ParameterEditorKind.Folder=>6,ParameterEditorKind.Range=>1,_=>p.Kind switch{ParameterKind.Integer or ParameterKind.Number=>1,ParameterKind.Boolean=>3,_=>-1}};
 public void ShowError(string message)=>error.Text=message;
 public void Rebuild(){if(rebuilding)return;BuildTree();selected.Children.Clear();var current=body();var ids=(current.Configuration.RunCategories??[]).Select(g=>g.Id).ToHashSet();var added=ids.Except(knownCategories).LastOrDefault();if(added is not null)selectedCategory=added;else if(selectedCategory is not null&&!ids.Contains(selectedCategory))selectedCategory=ids.FirstOrDefault();knownCategories=ids;categoryViews.Clear();var categoryControls=new StackPanel();categories(categoryControls,current);var categoryRows=categoryControls.Children.Cast<UIElement>().ToArray();categoryControls.Children.Clear();foreach(var old in top.Children.OfType<Button>().Where(b=>Equals(b.Tag,"GroupCategoryAdd")).ToArray())top.Children.Remove(old);var addCategory=(Button)categoryRows[0];addCategory.Content="添加组";DockPanel.SetDock(addCategory,Dock.Right);top.Children.Insert(1,addCategory);var header=Row();string[] titles={"数据源","自定义名称","类型","关联","数据同步","操作"};for(int i=0;i<6;i++)Cell(header,new TextBlock{Text=titles[i],FontWeight=FontWeights.Bold},i);selected.Children.Add(header);
  foreach(var category in new WorkflowRunCategory?[]{null}.Concat(current.Configuration.RunCategories??[])){var members=current.Configuration.RunParameters.Where(p=>p.CategoryId==category?.Id).ToArray();if(members.Length==0&&category is null)continue;var group=new StackPanel();var expander=new Expander{Header=category is null?(object)"未分组":CategoryHeader(category,categoryRows[1+current.Configuration.RunCategories!.ToList().FindIndex(g=>g.Id==category.Id)]),IsExpanded=category is null||expandedCategories.GetValueOrDefault(category.Id),Content=group};expander.BorderThickness=new Thickness(1);if(category is not null){categoryViews.Add(category.Id,expander);expander.Tag="GroupCategorySelect:"+category.Id;expander.BorderBrush=selectedCategory==category.Id?Brushes.DarkOrange:Brushes.Transparent;expander.Expanded+=(_,_)=>expandedCategories[category.Id]=true;expander.Collapsed+=(_,_)=>expandedCategories[category.Id]=false;expander.PreviewMouseLeftButtonDown+=(_,_)=>SelectCategory(category.Id);}selected.Children.Add(expander);foreach(var proxy in members){var node=current.Nodes.Single(n=>n.Id==proxy.NodeId);var descriptor=registry.GetDescriptor(node);var row=Row();Cell(row,new TextBlock{Text=node.Name+"."+proxy.Parameter,TextTrimming=TextTrimming.CharacterEllipsis,ToolTip=node.Name+"."+proxy.Parameter},0);var name=new TextBox{Text=proxy.Label,Tag="GroupRunLabel:"+proxy.Id};name.LostKeyboardFocus+=(_,_)=>{if(name.Text!=proxy.Label)Change(c=>{WorkflowConfiguration.CheckName(name.Text);return c with{RunParameters=c.RunParameters.Select(p=>p.Id==proxy.Id?p with{Label=name.Text}:p).ToArray()};});};Cell(row,name,1);Cell(row,new TextBlock{Text=proxy.IsInput?descriptor.Inputs.Single(p=>p.Name==proxy.Parameter).Kind.ToString():descriptor.Parameters.Single(p=>p.Name==proxy.Parameter).Kind.ToString()},2);
   var legacy=new StackPanel();commands(legacy,proxy,current);var commandLine=(DockPanel)legacy.Children[0];var controls=commandLine.Children.Cast<UIElement>().ToArray();commandLine.Children.Clear();var relation=new Grid();relation.ColumnDefinitions.Add(new());relation.ColumnDefinitions.Add(new(){Width=new GridLength(32)});var related=string.Join(",",proxy.Targets().Select(t=>t.NodeId).Distinct().Select(id=>current.Nodes.Single(n=>n.Id==id).Name));relation.Children.Add(new TextBlock{Text=related,ToolTip=related,TextTrimming=TextTrimming.CharacterEllipsis,VerticalAlignment=VerticalAlignment.Center});var link=(Button)controls[0];SubprogramCallWindow.NativeGroupIcon(link,"link");link.Width=32;link.ToolTip="关联参数";Grid.SetColumn(link,1);relation.Children.Add(link);Cell(row,relation,3);Cell(row,controls[1],4);var actions=new StackPanel{Orientation=System.Windows.Controls.Orientation.Horizontal};foreach(var control in controls.Skip(2).OfType<Button>().Where(b=>b.Tag?.ToString()?.StartsWith("GroupProxyUp:")==true||b.Tag?.ToString()?.StartsWith("GroupProxyDown:")==true))actions.Children.Add(control);var remove=new Button{Content="×",Tag="GroupRunDelete:"+proxy.Id};SubprogramCallWindow.NativeGroupIcon(remove,"delete");remove.Width=30;remove.Click+=(_,_)=>Change(c=>c with{RunParameters=c.RunParameters.Where(p=>p.Id!=proxy.Id).ToArray()});actions.Children.Add(remove);Cell(row,actions,5);group.Children.Add(row);
  }}
 }
